using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Business.Services;

public sealed class PharmacySettingsService(DatabaseInitializer db)
{
    public async Task<IReadOnlyDictionary<string,string>> GetAsync(CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT Key,Value FROM PharmacySettings ORDER BY Key";var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))values[r.GetString(0)]=r.GetString(1);return values;}
    public async Task SaveAsync(long actorId,IReadOnlyDictionary<string,string> settings,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,actorId,ct);await using var tx=await c.BeginTransactionAsync(ct);await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;foreach(var (key,value) in settings){if(key is "TaxesEnabled"&&value is not("0" or "1"))throw new ArgumentException("La taxe doit être désactivée ou activée explicitement.");if(key=="ExpiryAlertDays"&&(!int.TryParse(value,out var days)||days<1||days>3650))throw new ArgumentException("Le délai d'alerte doit être compris entre 1 et 3650 jours.");q.Parameters.Clear();q.CommandText="INSERT INTO PharmacySettings(Key,Value) VALUES($k,$v) ON CONFLICT(Key) DO UPDATE SET Value=excluded.Value";q.Parameters.AddWithValue("$k",key);q.Parameters.AddWithValue("$v",value);await q.ExecuteNonQueryAsync(ct);q.Parameters.Clear();q.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,OccurredAt,Details) VALUES($u,'PARAMETRE_MODIFIE','PharmacySettings',$d,$detail)";q.Parameters.AddWithValue("$u",actorId);q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));q.Parameters.AddWithValue("$detail",key);await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);}
}
